"use strict";(self.webpackChunkeggy_docs=self.webpackChunkeggy_docs||[]).push([[55],{1462(e){e.exports=JSON.parse('{"version":{"pluginId":"default","version":"current","label":"Next","banner":null,"badge":false,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"defaultSidebar":[{"type":"link","href":"/eggy/","label":"Introduction","docId":"intro","unlisted":false},{"type":"category","label":"Guides","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/eggy/guides/first-game","label":"Your first game","docId":"guides/first-game","unlisted":false},{"type":"link","href":"/eggy/guides/plugins","label":"Plugins","docId":"guides/plugins","unlisted":false}]}]},"docs":{"guides/first-game":{"id":"guides/first-game","title":"Your first game","description":"In this guide you make Cube Runner: an orange cube on a green floor that you drive with W, A, S and D and turn with the mouse, with a camera following behind. Along the way you meet the editor\'s panels, entities and components, and the code that makes them move.","sidebar":"defaultSidebar"},"guides/plugins":{"id":"guides/plugins","title":"Plugins","description":"A plugin is a Zig type that Eggy calls at set points in your game\'s life: when it starts, every frame, on input, and when it stops. Your game is a plugin too, the first one. Other plugins come from your own package or from other packages.","sidebar":"defaultSidebar"},"intro":{"id":"intro","title":"Introduction","description":"Eggy is a game engine for Zig 0.16. Your game is a Zig package that depends on Eggy: Eggy builds it into two programs, a runtime that players run and an editor for working on it.","sidebar":"defaultSidebar"}}}}')}}]);